	p, err := loadPipeline(pipelineFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	if errs := validatePipeline(p); len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		return 1
	}

	type expData struct {
		ID      string
		Params  map[string]string
		Metrics map[string]float64
	}
	experiments := []expData{}
	for _, combo := range parameterCombinations(p) {
		id := experimentID(combo)
		if !experimentStateExists(id) {
			continue
		}
		params, err := extractParamsFromExperimentID(p, id)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			return 1
		}
		metrics := map[string]float64{}
		for _, stage := range p.Stages {
			if st, err := readStageState(id, stage.Name); err == nil {
				for _, m := range st.Metrics {
					metrics[m.Name] = m.Value
				}
			}
		}
		experiments = append(experiments, expData{ID: id, Params: params, Metrics: metrics})
	}
	if len(experiments) == 0 {
		fmt.Fprintln(os.Stderr, "error: pipeline has not been run")
		return 1
	}

	paramNames := make([]string, 0, len(p.Parameters))
	for _, param := range p.Parameters {
		paramNames = append(paramNames, param.Name)
	}
	sort.Strings(paramNames)
	paramSet := make(map[string]bool, len(paramNames))
	for _, name := range paramNames {
		paramSet[name] = true
	}

	metricObjective := map[string]string{}
	for _, stage := range p.Stages {
		for _, m := range stage.Metrics {
			if m.Objective == "minimize" || m.Objective == "maximize" {
				metricObjective[m.Name] = m.Objective
			} else {
				metricObjective[m.Name] = "report"
			}
		}
	}
	allMetricNames := make([]string, 0, len(metricObjective))
	for name := range metricObjective {
		allMetricNames = append(allMetricNames, name)
	}
	sort.Strings(allMetricNames)

	headers := []string{"experiment_id"}
	headers = append(headers, paramNames...)
	for _, m := range allMetricNames {
		headers = append(headers, m)
		headers = append(headers, m+"_norm")
	}
	headers = append(headers, "composite_score")
	headers = append(headers, "pareto_optimal")

	if sortBy != "" {
		found := false
		for _, h := range headers {
			if h == sortBy {
				found = true
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "error: sort column %q not found\n", sortBy)
			return 1
		}
	}

	parsedFilters := make([]exportFilter, 0, len(filters))
	for _, expr := range filters {
		f, err := parseExportFilter(expr, headers)
		if err != nil {
			fmt.Fprintln(os.Stderr, "error:", err)
			return 1
		}
		parsedFilters = append(parsedFilters, f)
	}

	objMetrics := make([]string, 0, len(metricObjective))
	for name, obj := range metricObjective {
		if obj == "minimize" || obj == "maximize" {
			objMetrics = append(objMetrics, name)
		}
	}
	sort.Strings(objMetrics)

	minVal := map[string]float64{}
	maxVal := map[string]float64{}
	for _, m := range objMetrics {
		var vals []float64
		for _, exp := range experiments {
			if val, ok := exp.Metrics[m]; ok {
				vals = append(vals, val)
			}
		}
		if len(vals) > 0 {
			minVal[m] = minValue(vals)
			maxVal[m] = maxValue(vals)
		}
	}

	normalized := make([]map[string]float64, len(experiments))
	for i, exp := range experiments {
		normalized[i] = make(map[string]float64)
		for _, m := range objMetrics {
			val, ok := exp.Metrics[m]
			if !ok {
				continue
			}
			rng := maxVal[m] - minVal[m]
			var norm float64
			if rng == 0 {
				norm = 0.5
			} else if metricObjective[m] == "maximize" {
				norm = (val - minVal[m]) / rng
			} else {
				norm = (maxVal[m] - val) / rng
			}
			normalized[i][m] = norm
		}
	}

	composite := make([]string, len(experiments))
	if len(objMetrics) > 0 {
		for i := range experiments {
			if len(normalized[i]) == 0 {
				composite[i] = ""
				continue
			}
			sum := 0.0
			for _, m := range objMetrics {
				if norm, ok := normalized[i][m]; ok {
					sum += norm
				}
			}
			composite[i] = formatFloatFixed(round4(sum / float64(len(normalized[i]))), 4)
		}
	}

	pareto := make([]bool, len(experiments))
	if len(objMetrics) == 0 {
		for i := range experiments {
			pareto[i] = true
		}
	} else {
		for i := range experiments {
			pareto[i] = true
			for j := range experiments {
				if i == j {
					continue
				}
				if exportDominates(normalized[j], normalized[i], objMetrics) {
					pareto[i] = false
					break
				}
			}
		}
	}

	rows := make([]exportRow, len(experiments))
	for i, exp := range experiments {
		rows[i] = exportRow{
			id:         exp.ID,
			params:     exp.Params,
			metrics:    exp.Metrics,
			normalized: normalized[i],
			composite:  composite[i],
			pareto:     pareto[i],
		}
	}

	filtered := make([]exportRow, 0, len(rows))
	for _, row := range rows {
		match := true
		for _, f := range parsedFilters {
			val := exportCellString(row, f.column)
			ok, err := applyExportFilterValue(f, val)
			if err != nil {
				fmt.Fprintln(os.Stderr, "error:", err)
				return 1
			}
			if !ok {
				match = false
				break
			}
		}
		if match {
			filtered = append(filtered, row)
		}
	}
	rows = filtered

	sortExportRows(rows, headers, sortBy, descending)

	switch format {
	case "csv":
		writeExportCSV(headers, rows)
	case "json":
		writeExportJSON(headers, rows)
	case "markdown":
		writeExportMarkdown(headers, rows, paramSet)
	}
	return 0
}

type exportRow struct {
	id         string
	params     map[string]string
	metrics    map[string]float64
	normalized map[string]float64
	composite  string
	pareto     bool
}

type exportFilter struct {
	column string
	op    string
	value string
}

func extractParamsFromExperimentID(p *Pipeline, id string) (map[string]string, error) {
	params := map[string]string{}
	if len(p.Parameters) == 0 {
		if id != "exp_default" {
			return nil, fmt.Errorf("experiment ID %q does not match parameterless pipeline", id)
		}
		return params, nil
	}
	names := make([]string, 0, len(p.Parameters))
	for _, param := range p.Parameters {
		names = append(names, param.Name)
	}
	sort.Strings(names)
	if id == "exp_default" {
		return nil, fmt.Errorf("experiment ID %q does not match parameter definitions", id)
	}
	if !strings.HasPrefix(id, "exp_") {
		return nil, fmt.Errorf("invalid experiment ID %q", id)
	}
	rest := strings.TrimPrefix(id, "exp_")
	for i, name := range names {
		prefix := name + "="
		if !strings.HasPrefix(rest, prefix) {
			return nil, fmt.Errorf("experiment ID %q missing parameter %q", id, name)
		}
		rest = rest[len(prefix):]
		var val string
		if i == len(names)-1 {
			val = rest
			rest = ""
		} else {
			nextPrefix := "_" + names[i+1] + "="
			idx := strings.Index(rest, nextPrefix)
			if idx < 0 {
				return nil, fmt.Errorf("experiment ID %q missing parameter %q", id, names[i+1])
			}
			val = rest[:idx]
			rest = rest[idx+1:]
		}
		params[name] = val
	}
	return params, nil
}

func parseExportFilter(expr string, headers []string) (exportFilter, error) {
	ops := []string{">=", "<=", "!=", ">", "<", "="}
	for _, op := range ops {
		idx := strings.Index(expr, op)
		if idx > 0 {
			col := expr[:idx]
			val := expr[idx+len(op):]
			if col == "" {
				return exportFilter{}, fmt.Errorf("invalid filter expression: %q", expr)
			}
			found := false
			for _, h := range headers {
				if h == col {
					found = true
					break
				}
			}
			if !found {
				return exportFilter{}, fmt.Errorf("filter column %q not found", col)
			}
			if strings.HasSuffix(col, "_norm") {
				return exportFilter{}, fmt.Errorf("filtering on normalized column %q is not supported", col)
			}
			return exportFilter{column: col, op: op, value: val}, nil
		}
	}
	return exportFilter{}, fmt.Errorf("invalid filter expression: %q", expr)
}

func applyExportFilterValue(f exportFilter, val string) (bool, error) {
	switch f.op {
	case "=":
		return val == f.value, nil
	case "!=":
		return val != f.value, nil
	case ">", "<", ">=", "<=":
		a, err := strconv.ParseFloat(val, 64)
		if err != nil {
			return false, fmt.Errorf("numeric comparison on non-numeric value %q for column %q", val, f.column)
		}
		b, err := strconv.ParseFloat(f.value, 64)
		if err != nil {
			return false, fmt.Errorf("numeric comparison with non-numeric value %q", f.value)
		}
		switch f.op {
		case ">":
			return a > b, nil
		case "<":
			return a < b, nil
		case ">=":
			return a >= b, nil
		case "<=":
			return a <= b, nil
		}
	}
	return false, fmt.Errorf("unsupported operator %q", f.op)
}

func exportDominates(a, b map[string]float64, metrics []string) bool {
	strictlyBetter := false
	for _, m := range metrics {
		av, okA := a[m]
		bv, okB := b[m]
		if !okA || !okB {
			return false
		}
		if av < bv {
			return false
		}
		if av > bv {
			strictlyBetter = true
		}
	}
	return strictlyBetter
}
