func exportCellString(row exportRow, header string) string {
	switch header {
	case "experiment_id":
		return row.id
	case "composite_score":
		return row.composite
	case "pareto_optimal":
		if row.pareto {
			return "yes"
		}
		return "no"
	}
	if _, ok := row.params[header]; ok {
		return row.params[header]
	}
	if strings.HasSuffix(header, "_norm") {
		metric := strings.TrimSuffix(header, "_norm")
		if val, ok := row.normalized[metric]; ok {
			return formatFloatFixed(round4(val), 4)
		}
		return ""
	}
	if val, ok := row.metrics[header]; ok {
		return formatFloat(val)
	}
	return ""
}

func exportJSONValue(row exportRow, header string) interface{} {
	switch header {
	case "experiment_id":
		return row.id
	case "composite_score":
		if row.composite == "" {
			return nil
		}
		if n, err := strconv.ParseFloat(row.composite, 64); err == nil {
			return n
		}
		return row.composite
	case "pareto_optimal":
		if row.pareto {
			return "yes"
		}
		return "no"
	}
	if _, ok := row.params[header]; ok {
		return jsonNumberOrString(row.params[header])
	}
	if strings.HasSuffix(header, "_norm") {
		metric := strings.TrimSuffix(header, "_norm")
		if val, ok := row.normalized[metric]; ok {
			return round4(val)
		}
		return nil
	}
	if val, ok := row.metrics[header]; ok {
		return val
	}
	return nil
}

func jsonNumberOrString(s string) interface{} {
	if s == "" {
		return nil
	}
	if n, err := strconv.ParseFloat(s, 64); err == nil {
		return n
	}
	return s
}

func writeExportCSV(headers []string, rows []exportRow) {
	w := csv.NewWriter(os.Stdout)
	defer w.Flush()
	if err := w.Write(headers); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return
	}
	for _, row := range rows {
		record := make([]string, len(headers))
		for i, h := range headers {
			record[i] = exportCellString(row, h)
		}
		if err := w.Write(record); err != nil {
			fmt.Fprintln(os.Stderr, "error:", err)
			return
		}
	}
}

func writeExportJSON(headers []string, rows []exportRow) {
	var b strings.Builder
	b.WriteString("[")
	for i, row := range rows {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("{")
		for j, h := range headers {
			if j > 0 {
				b.WriteString(",")
			}
			key, _ := json.Marshal(h)
			b.Write(key)
			b.WriteString(":")
			val, _ := json.Marshal(exportJSONValue(row, h))
			b.Write(val)
		}
		b.WriteString("}")
	}
	b.WriteString("]")
	fmt.Println(b.String())
}

func writeExportMarkdown(headers []string, rows []exportRow, paramSet map[string]bool) {
	var b strings.Builder
	b.WriteString("|")
	for _, h := range headers {
		b.WriteString(" " + h + " |")
	}
	b.WriteString("\n|")
	for _, h := range headers {
		if h == "experiment_id" || paramSet[h] {
			b.WriteString(" --- |")
		} else {
			b.WriteString(" ---: |")
		}
	}
	b.WriteString("\n")
	for _, row := range rows {
		b.WriteString("|")
		for _, h := range headers {
			val := exportCellString(row, h)
			val = strings.ReplaceAll(val, "|", "\\|")
			b.WriteString(" " + val + " |")
		}
		b.WriteString("\n")
	}
	fmt.Print(b.String())
}

func sortExportRows(rows []exportRow, headers []string, sortBy string, desc bool) {
	if sortBy == "" {
		sort.SliceStable(rows, func(i, j int) bool {
			if desc {
				return rows[i].id > rows[j].id
			}
			return rows[i].id < rows[j].id
		})
		return
	}
	numeric := isNumericExportColumn(headers, sortBy, rows)
	sort.SliceStable(rows, func(i, j int) bool {
		a := exportCellString(rows[i], sortBy)
		b := exportCellString(rows[j], sortBy)
		var cmp int
		if numeric {
			na, errA := strconv.ParseFloat(a, 64)
			nb, errB := strconv.ParseFloat(b, 64)
			if errA == nil && errB == nil {
				if na < nb {
					cmp = -1
				} else if na > nb {
					cmp = 1
				}
			} else {
				if a < b {
					cmp = -1
				} else if a > b {
					cmp = 1
				}
			}
		} else {
			if a < b {
				cmp = -1
			} else if a > b {
				cmp = 1
			}
		}
		if cmp == 0 {
			return rows[i].id < rows[j].id
		}
		if desc {
			return cmp > 0
		}
		return cmp < 0
	})
}

func isNumericExportColumn(headers []string, col string, rows []exportRow) bool {
	if col == "experiment_id" || col == "pareto_optimal" {
		return false
	}
	if col == "composite_score" {
		return true
	}
	if strings.HasSuffix(col, "_norm") {
		return true
	}
	anyNonEmpty := false
	allNumeric := true
	for _, row := range rows {
		val := exportCellString(row, col)
		if val == "" {
			continue
		}
		anyNonEmpty = true
		if _, err := strconv.ParseFloat(val, 64); err != nil {
			allNumeric = false
			break
		}
	}
	return anyNonEmpty && allNumeric
}

func formatFloatFixed(f float64, precision int) string {
	return strconv.FormatFloat(f, 'f', precision, 64)
}
